/**
 * Morph — compiler-driven UI framework runtime.
 *
 * All Morph APIs (`CSS.load`, `morphState`, `morphEffect`, ...) are
 * statically analyzed and compiled into native code by the Morph compiler at
 * build time. This file is a runtime placeholder that exists so Node.js,
 * bundlers, and editor tooling can resolve `import ... from "morph"` without
 * errors. See `index.d.ts` for the full typed API surface.
 *
 * @module morph
 * @see index.d.ts
 */

/**
 * Build-time CSS loading API.
 *
 * `CSS.load()` is intercepted by the Morph compiler and replaced with the
 * generated style-injection code; the no-op below is never executed at
 * runtime. It exists only to keep CommonJS consumers resolvable.
 *
 * @type {{ load(path: string): void }}
 */
exports.CSS = {
  /** @param {string} path - Local stylesheet path or absolute URL. */
  load: function () {},
};
